insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('8f28c049-3703-53ed-a256-c7b987593a70', 'required_nonnative', 'Waived if English is one of your first languages, you attended a secondary school with English as the primary language of instruction for your entire secondary career, you are in or completed the IB Diploma or A Levels taught in English, or you scored 700+ on SAT EBRW or 29+ on ACT English or Reading. TOEFL Essentials and MyBest scores are not accepted; scores are valid two years.', '0d761106-cc81-5ff1-a3c9-da71ea88650c');
