insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('2d3f8334-1622-5d6c-b5d8-bb94e5907301', '2026-27', 'required', 'SAT or ACT required (reinstated from the Class of 2029). Students attending high school outside the U.S. may instead use 3 AP exams, IB Diploma results, A-Levels, or a standardized national exam. Multiple sittings are superscored; self-reporting allowed, official scores needed before enrolling.', 'a3c1d2c3-19dc-53cc-a5ac-f0220eaa01c9');
insert into application_requirements (institution_id, cycle, platforms, supplemental_essays, teacher_recs, counselor_rec, interview, portfolio, app_fee_usd, fee_waiver, css_profile_required, midyear_report, notes, source_id) values
 ('2d3f8334-1622-5d6c-b5d8-bb94e5907301', '2026-27', array['common_app','questbridge']::text[], 'Dartmouth Writing Supplement', 2, true, 'optional_informational', 'Optional art portfolio', 85, true, true, true, 'Also a recommended Peer Recommendation. Alumni interview is optional and not required for first-year applicants (CDS C7 lists the interview as ''considered''). The Apply page lists RD as Jan 1 in the timeline but ''January 2'' in one paragraph - confirm. Fee amount from the glossary page, which carries no date. QuestBridge Finalists have fees waived.', 'f9bc6429-af29-5203-b9c8-e96be12ab28c');
