insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('3a0e4180-56b3-5912-93c3-0d67ad9fa3aa', '2026-27', 'optional', 'IU Bloomington is test-optional: applicants choose whether SAT, ACT or CLT scores are considered, though the university encourages sharing them. Scores received by Jan 15 can still count for scholarship consideration.', '7bba2c0d-3bf0-5372-84dd-da1d1fb01ecd');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('3a0e4180-56b3-5912-93c3-0d67ad9fa3aa', '2026-27', array['common_app','own']::text[], 65, 'Apply IU application or Common App (no preference). An essay is required on either platform (Apply IU: IU-specific essay of 200-400 words). Fee shown on the freshman application page; the international page lists no separate fee.', '8db47fc9-1a29-5f38-871a-9c8401edfa21');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notification_date, notes, source_id) values
 ('5f7be4a7-eb62-55ea-bf22-4b8705905669', '3a0e4180-56b3-5912-93c3-0d67ad9fa3aa', '2026-27', 'application', 'EA', 'Early action (non-binding)', '2026-11-01', '2027-01-15', 'Highest admission and scholarship consideration; response by Jan 15 for complete applications.', '845a599f-fdea-5ed4-9649-42c57c2ff595'),
 ('b9beb0e5-bf90-5d97-8b4c-e3d64fce786c', '3a0e4180-56b3-5912-93c3-0d67ad9fa3aa', '2026-27', 'application', 'RD', 'Regular decision', '2027-02-01', '2027-03-15', 'Also the deadline for international-student merit scholarships (Global Engagement). After Feb 1 applications are considered only if space is available.', '845a599f-fdea-5ed4-9649-42c57c2ff595'),
 ('e2a967d5-c9f7-514e-8c0d-95c5ce8c54aa', '3a0e4180-56b3-5912-93c3-0d67ad9fa3aa', '2026-27', 'deposit', 'RD', 'Enrollment deposit ($100, nonrefundable)', '2027-05-01', null, null, '845a599f-fdea-5ed4-9649-42c57c2ff595');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('3a0e4180-56b3-5912-93c3-0d67ad9fa3aa', 'required_nonnative', 'Scores must be from within the last two years. Also accepted: SAT EBRW 560, ACT English 21; AP/IB/A-Level English results; citizenship of or 3 years of secondary school in a listed English-speaking country; IU Intensive English Program level 7. After admission, a second (higher) level is needed to skip English support courses (e.g. TOEFL 100, IELTS 7.5, Duolingo 130, PTE 68, SAT EBRW 710, ACT English 32), otherwise sub-scores decide placement.', '64920180-cbfe-5f52-961f-fa5256fad4cb');
