insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('35228703-5f8c-5c73-8e57-d772f27d443f', '2026-27', 'optional', 'Test optional. Scores may be self-reported at application; ACT science section not required.', '64604971-1c49-5f43-a7a8-af20e1997b2f');
insert into application_requirements (institution_id, cycle, platforms, supplemental_essays, teacher_recs, counselor_rec, interview, app_fee_usd, css_profile_required, notes, source_id) values
 ('35228703-5f8c-5c73-8e57-d772f27d443f', '2026-27', array['common_app','coalition','questbridge']::text[], false, 2, true, 'optional_informational', 0, true, 'Application is free beginning with the 2026-27 cycle. Use the essay prompts on the Common App/Coalition application; no supplemental essay. Request at least two teacher recommendations. Alumni interview is optional and may be requested after applying (not guaranteed); Glimpse video is the alternative; InitialView/Vericant interviews (paid) also accepted. Applicants may state a preference for September entry, February entry (a ''Feb'') or either. CSS Profile (code 3526) required of aid applicants; international applicants must file it online and apply for aid at the time of admission application.', '64604971-1c49-5f43-a7a8-af20e1997b2f');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('56781ab1-d11d-5cfd-b1fe-3afbbbe700e0', '35228703-5f8c-5c73-8e57-d772f27d443f', '2026-27', 'application', 'ED', 'Early Decision I', '2026-11-02', 'Decision mid-December (no exact date published). Aid forms due Nov 15 (CSS Profile).', '64604971-1c49-5f43-a7a8-af20e1997b2f'),
 ('4af7b9e9-92cd-5e5b-bf2d-d7b16a8c9167', '35228703-5f8c-5c73-8e57-d772f27d443f', '2026-27', 'application', 'ED2', 'Early Decision II', '2027-01-04', 'Decision mid-February (no exact date published). Admissions page lists Jan 4; the financial aid page lists Jan 3, 2027 for the aid forms.', '64604971-1c49-5f43-a7a8-af20e1997b2f'),
 ('b5b87af8-216b-5a73-9054-e1dd79710599', '35228703-5f8c-5c73-8e57-d772f27d443f', '2026-27', 'application', 'RD', 'Regular Decision', '2027-01-04', 'Decision late March (no exact date published). Aid forms due Feb 1, 2027.', '64604971-1c49-5f43-a7a8-af20e1997b2f');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('35228703-5f8c-5c73-8e57-d772f27d443f', 'required_nonnative', 'No English proficiency score is needed if your native language is English or your high-school classes were taught entirely in English for the last 3-4 years. All other applicants need verifiable TOEFL iBT, Duolingo English Test, IELTS or Cambridge English results. The page calls the scores below ''recommended'' minimums.', '64604971-1c49-5f43-a7a8-af20e1997b2f');
insert into english_requirements (institution_id, status, source_id, test_key, recommended_total, notes)
