insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('a0bc31fd-5254-5914-a037-bb1297d08b8f', '2026-27', 'optional', 'First-year applicants choose whether to have SAT/ACT scores considered; scores are self-reported in MyPennState. No superscore (highest combined score from a single test date); ACT Science not accepted. Required for the Accelerated Premedical-Medical Program.', '01e5f31a-e343-5eb9-a350-58bae218af06');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, fee_waiver, notes, source_id) values
 ('a0bc31fd-5254-5914-a037-bb1297d08b8f', '2026-27', array['common_app','own']::text[], 75, true, 'Apply through MyPennState or the Common App (no preference). Application fee is $75 for international applicants ($65 domestic). International first-years self-report courses via the STARS record (South Korean system: official records at application). SAT/ACT only if you wish them considered or use them as English proof. The pages reviewed do not mention essays, recommendations or an interview.', '1adb2cac-f5f2-535f-8196-d5c84eb4ac0e');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notification_date, notes, source_id) values
