insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('72d50d3c-d19a-5f32-ab10-e884f6a72409', '2026-27', 'optional', 'RIT is test-optional for all undergraduate programs; SAT/ACT is superscored if submitted. STEM applicants submitting ACT are advised to include the optional ACT Science section. International applicants are encouraged to submit SAT/ACT for scholarship review.', '202e7ac4-793e-5f52-80bc-9044b294ef21');
insert into application_requirements (institution_id, cycle, platforms, supplemental_essays, app_fee_usd, css_profile_required, notes, source_id) values
 ('72d50d3c-d19a-5f32-ab10-e884f6a72409', '2026-27', array['common_app','own']::text[], false, 65, false, 'Apply via the Common App or the free-standing RIT Application. A single essay is required; no supplemental essays unless applying to the Honors Program or Individualized Study BS. Minimum 1 recommendation letter (school counselor preferred, teacher letters welcome; up to 3-5 considered). Art/design/film programs require a portfolio. Fee waivers for hardship and military. Interview requirement not found on pages checked. The site does not state the year for each deadline column; the page also advertises Fall 2027 for Early Decision 1 / Early Action, so the dates are treated as the fall 2027 entry cycle.', '202e7ac4-793e-5f52-80bc-9044b294ef21');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('522cd756-cd95-5967-9584-04d725505bcd', '72d50d3c-d19a-5f32-ab10-e884f6a72409', '2026-27', 'application', 'ED', 'Early Decision I (binding)', '2026-11-01', 'Decision mid-December (no exact date); $500 deposit due Jan 15.', '202e7ac4-793e-5f52-80bc-9044b294ef21'),
 ('b87a7fc0-4755-555b-8f2b-6b1c413b609f', '72d50d3c-d19a-5f32-ab10-e884f6a72409', '2026-27', 'application', 'EA', 'Early Action', '2026-11-01', 'Decision late January (no exact date); reply by May 1.', '202e7ac4-793e-5f52-80bc-9044b294ef21'),
 ('3a8284c6-f203-5fba-888e-40dd2b7dabfb', '72d50d3c-d19a-5f32-ab10-e884f6a72409', '2026-27', 'application', 'ED2', 'Early Decision II (binding)', '2027-01-01', 'Decision mid-January (no exact date); $500 deposit due Feb 15.', '202e7ac4-793e-5f52-80bc-9044b294ef21'),
 ('1db1fe33-2c3f-55fc-bae2-bf98409c226f', '72d50d3c-d19a-5f32-ab10-e884f6a72409', '2026-27', 'application', 'RD', 'Regular Decision', '2027-01-15', 'Decision mid-March (no exact date); reply by May 1. Later applications are reviewed on a space-available basis.', '202e7ac4-793e-5f52-80bc-9044b294ef21');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('72d50d3c-d19a-5f32-ab10-e884f6a72409', 'required_nonnative', 'Not required for applicants from a listed set of English-speaking countries (e.g. USA, UK, Canada except Quebec, Australia, New Zealand, Ireland, Singapore, Nigeria, Kenya), based on citizenship and/or 2+ years of study there. Scores can be self-reported at application; official scores required on enrollment. Scores below the direct-admission minimum lead to conditional admission with required English-language instruction.', 'bffd12fa-4664-5cb2-b1de-10ec2ccc9a52');
