select '095edeb3-f3f8-5647-ba8f-e2be1569a1cc'::uuid, 'required_option', '5e83d2f4-1421-5d21-bfe3-5ed5a06415d5'::uuid, v.* from (values
 ('TOEFL_IBT', 79, 'Old 0-120 scale, tests through 2026-01-21. Pharmacy and Nursing require 100.'),
 ('TOEFL_IBT_2026', 4.5, 'New scale, tests from 2026-01-22. Pharmacy and Nursing require 5.5. No section minimums listed.'),
 ('IELTS', 6.5, null),
 ('DUOLINGO', 115, 'Pharmacy and Nursing require 130.'),
