insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('e50b5917-e166-5374-ae30-9474e1d71ed4', '2026-27', 'optional', 'SAT/ACT optional for the 2026-27 cycle; applicants can also choose to suppress scores already sent. SAT is superscored, ACT is not; SAT/ACT writing sections are not considered. Self-reported scores accepted; enrolling students must send official scores (if they took a test).', '5089cba4-3419-5dc4-b7c0-8f13a4f66f43');
insert into application_requirements (institution_id, cycle, platforms, supplemental_essays, teacher_recs, counselor_rec, app_fee_usd, css_profile_required, notes, source_id) values
 ('e50b5917-e166-5374-ae30-9474e1d71ed4', '2026-27', array['common_app','coalition','questbridge']::text[], true, 2, true, 60, true, 'Two Swarthmore short answers (max 250 words each) on the Common App / Coalition application. Interviews are offered and optional (no disadvantage if skipped); the page does not say whether they are evaluative. Applicants whose schooling is outside the U.S. must submit one of: Swarthmore Video Response, an English proficiency exam, or an InitialView/Vericant video. CSS Profile is required only from international students who apply for aid, after admission (fee waived).', '8dfe06d9-43f8-5b80-98c7-cc2ee30a0c2d');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notification_date, notes, source_id) values
 ('484aa4c9-2428-596e-8a65-e7ef82fcbb0c', 'e50b5917-e166-5374-ae30-9474e1d71ed4', '2026-27', 'application', 'ED', 'Early Decision I', '2026-11-15', null, 'Decisions released online in mid-December (no exact date published). Requires the ED agreement and first-quarter senior grades.', '8dfe06d9-43f8-5b80-98c7-cc2ee30a0c2d'),
