insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notification_note, notes, source_id) values
 ('f515c17d-4a25-585b-894f-d1d8e9e9b389', 'ba6f6326-df17-5b28-9055-e105ba1840ee', '2026-27', 'application', 'RD', 'UC application filing period closes', '2026-11-30', 'Admission decisions released March 1-31, 2027 (some campuses earlier)', 'No early plans. Application opens August 1, 2026 for fall 2027. Self-report English test scores in the application; UCLA asks that they be reported by January.', 'ae8c3e0e-3664-526d-b8c1-004c7780fec3'),
 ('bca1d8e7-549e-56ee-b386-95fb4d323a38', 'ba6f6326-df17-5b28-9055-e105ba1840ee', '2026-27', 'deposit', null, 'Statement of Intent to Register (SIR)', '2027-05-01', null, null, 'ae8c3e0e-3664-526d-b8c1-004c7780fec3');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('ba6f6326-df17-5b28-9055-e105ba1840ee', 'required_nonnative', 'Required if all or some secondary school was in a country where English was not the language of instruction and you have had less than 3 years of instruction in English. UCLA may also require its English-as-a-Second-Language Placement Exam after admission.', '32f3d373-c684-5288-bffd-29919fde8992');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, recommended_total, notes)
select 'ba6f6326-df17-5b28-9055-e105ba1840ee'::uuid, 'required_option', 'b6dc7bc9-e312-5094-9d15-086a6de2bdd2'::uuid, v.* from (values
 ('TOEFL_IBT', 80, 100, 'UC minimum 80 (tests before Jan 2026). UCLA looks for competitive scores: above 100 with every section above 24.'),
 ('TOEFL_IBT_2026', 4.5, 5.0, 'UC minimum 4.5 (Jan 2026 or later). UCLA looks for 5 or higher with every section 5 or higher.'),
 ('IELTS', 6.5, 7.5, 'UCLA looks for 7.5 or above.'),
 ('DUOLINGO', 115, 135, 'UCLA looks for 135 or higher.')) v;
insert into score_codes (institution_id, test_key, code, notes, source_id)
select 'ba6f6326-df17-5b28-9055-e105ba1840ee'::uuid, v.* from (values
 ('sat', '4837', 'UCLA is test-blind: SAT/ACT are not considered for admission or scholarships; codes apply only to scores sent after admission.', 'c7357df9-1e4d-547f-ae92-32c179bd0c06'::uuid),
 ('act', '0448', 'UCLA is test-blind; code applies only to scores sent after admission.', 'c7357df9-1e4d-547f-ae92-32c179bd0c06'::uuid),
 ('toefl', null, 'No undergraduate TOEFL code is published. Self-report scores in the UC application; UCLA says a TOEFL report sent to one UC campus reaches all campuses you apply to.', '32f3d373-c684-5288-bffd-29919fde8992'::uuid),
 ('ielts', null, 'No code. UCLA says IELTS results must be sent to each campus you apply to; self-report in the application.', '32f3d373-c684-5288-bffd-29919fde8992'::uuid),
 ('duolingo', null, 'No code. DET scores are sent through the DET portal with your UC Application ID, once per campus.', '32f3d373-c684-5288-bffd-29919fde8992'::uuid)) v;
insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, room_board_usd, books_usd, other_usd, total_coa_usd, intl_aid_policy, intl_need_aid, merit_scholarships, notes, source_id) values
 ('ba6f6326-df17-5b28-9055-e105ba1840ee', '2023-2024', 15729, 53331, 18960, 1680, 6798, 41373, 'none', false, false, 'College Scorecard (IPEDS 2023-24): tuition includes required fees; on-campus cost of attendance.; UCLA''s admissions site says it does not award scholarships or financial aid to undergraduates who are not U.S. citizens or permanent residents; admitted internationals must show funds (about $80,739 minimum for fall 2026 entrants). UCLA''s financial aid site says internationals may be eligible only for outside scholarships, private loans and short-term loans.', '561e0e9a-59f0-5bae-aa16-01bc46d4144b');
insert into institution_tiers (institution_id, category_key, tier_code, rationale)
select 'ba6f6326-df17-5b28-9055-e105ba1840ee'::uuid, v.* from (values
 ('general', 'A++', 'Admit rate 9.4%'),
 ('computer_science', 'A', 'Top-15 CS program in Samueli School of Engineering.'),
 ('engineering', 'A', 'Samueli is a top-15 engineering school.'),
 ('biology_life_sci', 'A', 'Top-15 life sciences with a major medical center.'),
 ('pre_med', 'A', 'Strong pre-med research access through UCLA Health and the Geffen School of Medicine.'),
 ('economics', 'A', 'Top-15 economics department.'),
 ('math_physics', 'A', 'Top-15 mathematics and physics.'),
 ('humanities', 'A', 'Top-15 humanities departments.'),
 ('arts_design', 'S', 'School of Theater, Film & Television and School of the Arts & Architecture are among the leading US arts schools.'),
 ('nursing', 'A', 'School of Nursing BS is a top-15 undergraduate nursing program.')) v;
insert into major_admissions (id, institution_id, program, category_key, admit_model, capped, notes) values
 ('c0d55437-11b1-5ca9-a542-a6a4723fa45b', 'ba6f6326-df17-5b28-9055-e105ba1840ee', 'College of Letters and Science (first-year, incl. undeclared)', 'humanities', 'school_college', false, 'UCLA says that for College applicants the chosen major is not considered in admission review; changing majors within the College is not allowed during the application process, and about 1,500 students are undeclared at any time.');

