insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('b78d08d2-3ed6-5eba-bdad-7888146c3bc7', 'required_nonnative', 'Required for international (temporary visa) students except those from listed exempt countries, and for non-international students whose first language is not English or who studied in U.S. schools fewer than four years. May be waived via ACT (English and Reading 21, Writing 8) or SAT (EBRW 540; digital SAT Reading & Writing 550), AP/A-level/IB English coursework, or an exemption request. The minimum must be met on a single test date (no MyBest).', '772bf25a-4c4a-5eb0-b4dc-99ee6fb4a1f9');
