insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('0bdbab7a-c9ef-5b09-a7cb-c393402bc138', '2026-27', 'optional', 'SAT/ACT permanently not required. Reviewers do not see scores if sent; scores above the middle 50% (about 1400 SAT / 31 ACT) may help a handful of applicants. Homeschooled applicants and applicants from schools without letter or numeric grades must still submit SAT or ACT.', '930db862-9215-5d9e-9118-9522d9906012');
insert into application_requirements (institution_id, cycle, platforms, supplemental_essays, teacher_recs, counselor_rec, interview, app_fee_usd, notes, source_id) values
 ('0bdbab7a-c9ef-5b09-a7cb-c393402bc138', '2026-27', array['common_app']::text[], 'Common App personal essay (650 words max); the page lists no separate supplement.', 0, false, 'not_offered', 95, 'Application fee is $95 for international first-year applicants (no fee waivers) and $85 for US applicants (waivers available). Courses and grades are self-reported through STARS; transcripts are uploaded unofficially only if the school follows a national curriculum outside the U.S. The UW asks applicants not to send letters of recommendation, does not conduct interviews and does not consider demonstrated interest. First choice major matters for Direct-to-Major/College programs.', 'df0aa5de-7be2-55de-99aa-f8f4dcf8f75b');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('4201a26e-228f-5545-a4ff-6b0537090f64', '0bdbab7a-c9ef-5b09-a7cb-c393402bc138', '2026-27', 'application', 'RD', 'Application deadline (summer and autumn quarter)', '2026-11-15', 'Common App only; no early plans. Decisions released March 1-15, 2027 (no single date published). Test-score (English proficiency) deadline is December 31; the UW has no early action or early decision.', 'dc6ad2cc-7242-5937-8568-20af21aa5400'),
 ('979c0517-cdf5-54dc-b0b7-03e48a25e188', '0bdbab7a-c9ef-5b09-a7cb-c393402bc138', '2026-27', 'financial_aid', 'RD', 'FAFSA/WASFA priority date', '2027-02-01', 'Applies to US citizens, permanent residents and eligible students only; the UW does not provide aid to undergraduate international students.', 'dc6ad2cc-7242-5937-8568-20af21aa5400');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('0bdbab7a-c9ef-5b09-a7cb-c393402bc138', 'required_nonnative', 'Exempt if primary and secondary education took place in Australia, Canada (English-speaking provinces), the UK, Ireland, New Zealand or the U.S. (birth in those countries alone does not exempt). Alternative: SAT EBRW 580+ or ACT English 22+ with an average grade of B in English writing/literature courses taught in English in grades 10-12. Exams must be taken by Dec 31; no conditional admission, no MyBest, no superscoring.', '5a16034b-a2b3-5761-85d5-73400e8e79f6');
