insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('29b755b7-4fc7-561e-b2a5-e257d04e010d', '2026-27', 'optional', 'Standardized testing is optional and requirements are described as flexible: SAT, ACT, national exam results, IB, A-Levels or AP/IB exams may be submitted.', '72a46788-7636-5873-bdef-27646d910d6c');
insert into application_requirements (institution_id, cycle, platforms, supplemental_essays, teacher_recs, counselor_rec, interview, app_fee_usd, fee_waiver, css_profile_required, notes, source_id) values
 ('29b755b7-4fc7-561e-b2a5-e257d04e010d', '2026-27', array['common_app','coalition','questbridge']::text[], '250-word response on what you want to study and why; Signature Scholar Programs need a 250-word short answer per program; optional 90-second video. Portfolio required for the College of Art and strongly encouraged for Architecture.', 1, true, 'not_offered', 75, true, true, 'One teacher evaluation and one counselor recommendation. WashU does not conduct evaluative interviews; third-party interview supplements such as InitialView are encouraged but optional and not submitting one is not a disadvantage. CSS Profile is part of the financial aid application (required for aid applicants). QuestBridge is listed as an application route but its dates are on QuestBridge''s site. Early Action is a newly added round.', '72a46788-7636-5873-bdef-27646d910d6c');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notification_date, notes, source_id) values
 ('8b4f9950-b779-51d9-9df6-563f84e9fb2e', '29b755b7-4fc7-561e-b2a5-e257d04e010d', '2026-27', 'application', 'EA', null, '2026-11-02', '2026-12-23', 'Newly added nonbinding Early Action round; decisions released by Dec 23; reply due May 1. Page labels these dates ''Fall 2027 first-year applicants'' without writing the calendar year.', '286e27b0-dd68-5481-97d7-6c6b8f079ede'),
