insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('2c4d6cbd-6838-5c12-ac11-2a3b974e8f7c', '2026-27', 'optional', 'SAT/ACT scores are completely optional; W&M does not require them. Forty percent of the Class of 2029 applied test-optional.', 'e3b59768-119e-5339-893c-a75e670567f9');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('2c4d6cbd-6838-5c12-ac11-2a3b974e8f7c', '2026-27', array['common_app']::text[], 75, 'Checklist lists the Common App, high school transcript, essay and recommendation letters; the exact number of teacher recommendations and supplemental essays was not stated on the pages read. $75 non-refundable fee with a fee-waiver request option. Supplemental materials (transcripts, scores, recommendations) may arrive after the deadline.', '902c2e0c-e857-588b-9f39-92fb04c58182');
