insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('0484af38-0265-5b9f-aea4-0095a7ef5c5e', '2026-27', 'optional', 'Test-optional (applicants choose whether scores are considered; no-harm practice). SAT is superscored; ACT best composite is used; science section not required. Self-reporting allowed; official scores only if you enroll. Scores are not used for merit scholarships. Last published middle 50% (fall 2021 entrants who submitted): SAT 1340-1480, ACT 30-34.', '408920a7-8fca-505b-99c5-4d1b93d11b1f');
insert into application_requirements (institution_id, cycle, platforms, teacher_recs, counselor_rec, app_fee_usd, css_profile_required, notes, source_id) values
 ('0484af38-0265-5b9f-aea4-0095a7ef5c5e', '2026-27', array['common_app']::text[], 1, true, 70, true, 'One teacher and one counselor recommendation, official transcripts (first marking period grades or mid-year report highly recommended). Early Decision applicants submit the ED Agreement form. Page says all first-year candidates use the Common Application. International students applying for need-based aid submit only the CSS Profile (no FAFSA); domestic need-based applicants need both.', 'ca242580-b055-582a-bb37-b71e899a6504');
